```swift
func replaceHomophones(sentence: String, homophones: [String]) -> String {
    let words = sentence.components(separatedBy: .whitespacesAndNewlines)
    var newSentence = ""
    for word in words {
        if isHomophone(word: word, homophones: homophones) {
            newSentence += "[" + homophones.first(where: { $0 != word })! + "] "
        } else {
            newSentence += word + " "
        }
    }
    return newSentence.trimmingCharacters(in: .whitespacesAndNewlines)
}
