```matlab
% Function to convert a single character to its Morse Code representation
function morse_code = char_to_morse(char)
    % Convert the character to uppercase
    char = upper(char);

    % Map the character to its Morse Code representation
    switch char
        case 'A'
            morse_code = '.-';
        case 'B'
            morse_code = '-...';
        case 'C'
            morse_code = '-.-.';
        case 'D'
            morse_code = '-..';
        case 'E'
            morse_code = '.';
        case 'F'
            morse_code = '..-';
        case 'G'
            morse_code = '--.';
        case 'H'
            morse_code = '....';
        case 'I'
            morse_code = '..';
        case 'J'
            morse_code = '.---';
        case 'K'
            morse_code = '-.';
        case 'L'
            morse_code = '.-..';
        case 'M'
            morse_code = '--';
        case 'N'
